describe('Reading Order Matches Visual Order', () => {
  beforeEach(() => {
    cy.visit('/page');
  });

  it('should read content in the same order as it appears visually', () => {
    // Verify the page loads with visible content
    cy.get('[data-testid="page-content"]').should('be.visible');

    // Verify the first visible element is a heading
    cy.get('[data-testid="page-heading"]').should('contain', 'Welcome to Our Page');

    // Verify the first visible paragraph follows the heading
    cy.get('[data-testid="page-paragraph"]').should('contain', 'This is the first paragraph of our page.');

    // Verify the second visible element is a subheading
    cy.get('[data-testid="page-subheading"]').should('contain', 'Subheading');

    // Verify the second visible paragraph follows the subheading
    cy.get('[data-testid="page-paragraph"]').should('contain', 'This is the second paragraph.');

    // Verify the third visible element is a list
    cy.get('[data-testid="page-list"]').should('contain', 'List Item 1');

    // Verify the first list item is visible
    cy.get('[data-testid="list-item-1"]').should('be.visible');

    // Verify the fourth visible element is a button
    cy.get('[data-testid="page-button"]').should('be.visible');

    // Verify the button is visible and has the correct text
    cy.get('[data-testid="page-button"]').should('contain', 'Click Me');

    // Verify the fifth visible element is a footer
    cy.get('[data-testid="page-footer"]').should('be.visible');

    // Verify the footer contains copyright information
    cy.get('[data-testid="page-footer"]').should('contain', '© 2023 Company');

    // Verify the page has no hidden content
    cy.get('[data-testid="page-content"]').should('have.length.greaterThan', 0);
  });

  it('should handle content with dynamic visibility based on user interaction', () => {
    // Verify the page loads with initial content
    cy.get('[data-testid="page-content"]').should('be.visible');

    // Click the button to reveal hidden content
    cy.get('[data-testid="page-button"]').click();

    // Verify the hidden content is now visible
    cy.get('[data-testid="page-hidden-content"]').should('be.visible');

    // Verify the hidden content appears after the button
    cy.get('[data-testid="page-hidden-content"]').should('contain', 'This content was hidden before');

    // Verify the reading order is still maintained
    cy.get('[data-testid="page-heading"]').should('contain', 'Welcome to Our Page');
    cy.get('[data-testid="page-paragraph"]').should('contain', 'This is the first paragraph of our page.');

    // Verify the hidden content does not disrupt the visual order
    cy.get('[data-testid="page-hidden-content"]').should('be.visible');

    // Verify the footer remains visible and unchanged
    cy.get('[data-testid="page-footer"]').should('be.visible');

    // Verify the page does not have any broken or missing elements
    cy.get('[data-testid="page-content"]').should('have.length.greaterThan', 0);
  });
});
